test:
def drain(it):
    values = []
    while True:
        try:
            values.append(next(it))
        except StopIteration:
            return values
assert drain(MultiDimensionalIterator([1, 2])) == [1, 2]
assert drain(MultiDimensionalIterator([[1, []], [], [2, 3]])) == [1, 2, 3]
assert drain(MultiDimensionalIterator([[[1], []], [[2, 3]], []])) == [1, 2, 3]
